package propertyrental.platform.location.application.mapper;

import org.springframework.stereotype.Component;

import propertyrental.platform.location.api.dto.request.CreateCityRequest;
import propertyrental.platform.location.api.dto.request.UpdateCityRequest;
import propertyrental.platform.location.api.dto.response.CityResponse;
import propertyrental.platform.location.infrastructure.persistence.entity.CityEntity;

@Component
public class CityMapper {

    // This build a new entity from a create request (the id is generated by the database)
    public CityEntity toEntity(CreateCityRequest request) {
        CityEntity city = new CityEntity();
        city.setProvinceId(request.provinceId());
        city.setName(request.name());

        return city;
    }

    // This applies an update request to an existing entity in place
    public void updateEntity(CityEntity city, UpdateCityRequest request) {
        city.setProvinceId(request.provinceId());
        city.setName(request.name());
    }

    // This one converts an entity to the response DTO so that the entity is never exposed
    public CityResponse toResponse(CityEntity city) {

        return new CityResponse(city.getId(), city.getProvinceId(), city.getName());
    }
}